<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api, errorMessage } from '../api.js'
import { useAuth } from '../stores/auth.js'
import { formatTime } from '../time.js'
import StatusBadge from '../components/StatusBadge.vue'
const auth = useAuth(), data = ref(null), error = ref(''), busy = ref(false)
const greeting = computed(() => `Hello, ${auth.user?.displayName?.split(' ')[0] || 'there'}.`)
let timer
async function load() { if (busy.value) return; busy.value = true; try { data.value = (await api.get('/dashboard')).data; error.value = '' } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(() => { load(); timer = setInterval(load, 15000) }); onUnmounted(() => clearInterval(timer))
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR PERSONAL OVERVIEW</span><h1>{{ greeting }} <span class="wave">✦</span></h1><p>A clear mind starts with a little planning.</p></div><RouterLink class="button primary" to="/reminders/new">+ Create reminder</RouterLink></div><p v-if="error" class="notice error" role="alert">{{ error }} <button class="text-button" @click="load">Try again</button></p><section class="hero-card"><div><span class="eyebrow purple">A LITTLE AHEAD OF LIFE</span><h2>Big plans.<br>Small reminders.</h2><p>Keep the important moments on your calendar<br class="desktop-only"> and off your mind. We’ll take it from here.</p><RouterLink to="/reminders/new" class="button dark">Plan something →</RouterLink></div><div class="hero-calendar" aria-hidden="true"><div class="calendar-top"><span></span><span></span></div><div class="calendar-body"><small>YOUR NEXT MOMENT</small><strong>✓</strong><span>Right on time.</span></div><span class="floating-star">✦</span><span class="floating-dot"></span></div></section><div v-if="!data" class="loading-block" role="status">{{ busy ? 'Loading your workspace…' : 'Your overview will appear here.' }}</div><template v-else><section class="stats-grid"><article class="stat-card"><span class="stat-icon lavender">◫</span><span>Total reminders</span><strong>{{ data.total }}</strong><small>Your plans in one place</small></article><article class="stat-card"><span class="stat-icon amber">◷</span><span>Waiting to send</span><strong>{{ data.pending + data.retry }}</strong><small>{{ data.retry }} awaiting a retry</small></article><article class="stat-card"><span class="stat-icon mint">↗</span><span>SMTP accepted</span><strong>{{ data.sent }}</strong><small>Accepted by the email provider</small></article><article class="stat-card"><span class="stat-icon rose">!</span><span>Needs attention</span><strong>{{ data.failed }}</strong><small>Failed or uncertain attempts</small></article></section><section class="dashboard-columns"><article class="panel"><div class="panel-heading"><div><h2>Coming up next</h2><p>Your next scheduled moments</p></div><RouterLink to="/reminders" class="text-link">View all ↗</RouterLink></div><div v-if="!data.upcoming.length" class="empty-state"><span>◷</span><h3>A little breathing room.</h3><p>Your upcoming reminders will appear here.</p><RouterLink to="/reminders/new" class="text-link">Create your first reminder →</RouterLink></div><div v-for="r in data.upcoming" :key="r.id" class="upcoming-row"><span class="reminder-icon">◷</span><div class="grow"><strong>{{ r.title }}</strong><small>{{ formatTime(r.nextAttemptAt, r.timeZone) }} · {{ r.timeZone }}</small><small>{{ r.recipientEmail }}</small></div><StatusBadge :status="r.status" /></div></article><article class="panel"><div class="panel-heading"><div><h2>Recent activity</h2><p>Every attempt, accounted for</p></div><RouterLink to="/history" class="text-link">History ↗</RouterLink></div><div v-if="!data.recentActivity.length" class="empty-state"><span>↗</span><h3>A fresh beginning.</h3><p>Email activity will appear after your first sending attempt.</p></div><div v-for="log in data.recentActivity" :key="log.id" class="activity-row"><span class="activity-dot" :class="log.status.toLowerCase()"></span><div class="grow"><strong>{{ log.reminderTitle }}</strong><small>Attempt {{ log.attemptNumber }} · {{ formatTime(log.startedAt, auth.user?.timeZone) }}</small></div><StatusBadge :status="log.status" /></div></article></section><p class="fine-print">SMTP acceptance confirms provider submission. It does not confirm inbox delivery. Overview refreshes every 15 seconds.</p></template></template>
